import org.gradle.internal.declarativedsl.schemaBuilder.treatInterfaceAsConfigureLambda

/*
 * This file was generated by the Gradle 'init' task.
 */

plugins {
    `java-library`
    `maven-publish`
    id("com.gradleup.shadow") version "9.6.1"
}

repositories {
    mavenLocal()
    mavenCentral()
    maven {
        url = uri("https://repo.papermc.io/repository/maven-public/")
    }

    maven {
        url = uri("https://repo.tcoded.com/releases")
    }
}

dependencies {
    api(libs.com.tcoded.folialib)
    api(libs.dev.triumphteam.triumph.gui)
    compileOnly(libs.io.papermc.paper.paper.api)
    compileOnly(libs.com.zezdathecrystaldragon.fourthchance)
}

group = "com.zezdathecrystaldragon.com"
version = "1.0-SNAPSHOT"
description = "SavingPrivateRahya"
java.sourceCompatibility = JavaVersion.VERSION_25

publishing {
    publications.create<MavenPublication>("maven") {
        from(components["shadow"])
    }
}

tasks.jar {
    archiveClassifier.set("naked")
}

tasks.shadowJar {
    archiveClassifier.set("")
    relocate("dev.triumphteam.gui", "com.zezdathecrystaldragon.gui")
    relocate("com.tcoded.folialib", "com.zezdathecrystaldragon.folialib")
}

tasks.build {
    dependsOn(tasks.publishToMavenLocal)
}

tasks.publishToMavenLocal {}

tasks.withType<JavaCompile>() {
    options.encoding = "UTF-8"
}

tasks.withType<Javadoc>() {
    options.encoding = "UTF-8"
}
